/* Album pages use catalog track IDs, shared previews, and the normal add flow. */
(function(root){
 function sources(media){
  const rows=[media,...(media.version_options||[])].flatMap(m=>m.source_records||[m]).filter(m=>m.kind==='album');
  const linked=rows.flatMap(m=>{const refs=[];for(const [provider,id] of Object.entries(m.external_ids||{})){if(provider==='spotify'&&/^[a-zA-Z0-9]{22}$/.test(id)||provider==='apple'&&/^[1-9][0-9]*$/.test(id))refs.push({kind:'album',title:m.title,source:{provider,id}});}for(const link of m.media_links||[]){try{const u=new URL(link.url),match=u.pathname.match(/^\/album\/([a-zA-Z0-9]{22})\/?$/);if(u.protocol==='https:'&&u.hostname==='open.spotify.com'&&match)refs.push({kind:'album',title:m.title,source:{provider:'spotify',id:match[1]}});}catch{}}return refs;});
  const unique=new Map();for(const m of [...rows,...linked])if(['spotify','apple','musicbrainz'].includes(m.source.provider)&&!unique.has(m.source.provider+':'+m.source.id))unique.set(m.source.provider+':'+m.source.id,m);const selected=m=>m.source.provider===media.source.provider&&m.source.id===media.source.id;return [...unique.values()].sort((a,b)=>Number(selected(b))-Number(selected(a))); 
 }

 if(typeof module==='object')module.exports={sources};if(typeof document==='undefined')return;
 const names={spotify:'Spotify',apple:'Apple Music',musicbrainz:'MusicBrainz'},cache=new Map(),bindings=new Map();
 document.addEventListener('submit',()=>queueMicrotask(()=>{for(const [section,rows] of bindings){if(!section.isConnected){bindings.delete(section);continue;}section.querySelectorAll('[data-track-add]').forEach(b=>{const m=rows[Number(b.dataset.trackAdd)],saved=owned(fromMetadata(m));b.disabled=!!saved;b.textContent=saved?'✓ In library':'+ Add';b.setAttribute('aria-label',(saved?'In library':'Add song')+': '+m.title);});}}));
 function bind(container){const hero=container.querySelector('.media-hero'),media=hero&&FolioMediaInfo.forElement(hero);if(media?.kind!=='album'||container.querySelector('.album-tracks'))return;const options=sources(media);if(!options.length)return;
  const section=document.createElement('section');section.className='live-detail-section album-tracks';section.innerHTML=`<h3>Tracks</h3><div class="album-track-tools"><label>Track listing<select aria-label="Album track listing source">${options.map((m,i)=>`<option value="${i}">${esc(names[m.source.provider])} · ${esc(m.facts?.Edition||'Edition '+(options.filter(x=>x.source.provider===m.source.provider).indexOf(m)+1))}</option>`).join('')}</select></label><button type="button" class="album-refresh">↻ Refresh tracks</button></div><p class="album-track-status" role="status">Loading tracks…</p><div class="album-track-list"></div><button type="button" class="album-more" hidden>Load more tracks</button>`;
  const overview=container.querySelector('.media-overview');if(overview)overview.after(section);else hero.after(section);
  let records=[],page=0,generation=0,controller;
  async function load(append=false,force=false){const current=++generation;controller?.abort();controller=new AbortController();const album=options[Number(section.querySelector('select').value)],next=append?page+1:1,path=`albums/${album.source.provider}/${album.source.id}/tracks?page=${next}`;section.setAttribute('aria-busy','true');section.querySelector('.album-track-list').inert=true;section.querySelector('.album-track-status').textContent='Loading album tracks…';section.querySelector('.album-more').disabled=true;
   try{const data=!force&&cache.has(path)?cache.get(path):await metadataGet(path,controller.signal,force);if(current!==generation||!section.isConnected)return;cache.set(path,data);while(cache.size>24)cache.delete(cache.keys().next().value);records=append?[...records,...data.results]:data.results;records=[...new Map(records.map(m=>[JSON.stringify([m.facts?.Disc,m.facts?.['Track number'],m.id]),m])).values()];page=next;bindings.set(section,records);
    section.querySelector('.album-track-status').innerHTML=`${records.length} tracks loaded${data.edition?' · Edition: '+esc(data.edition):''}. <a href="${esc(safeMediaUrl(data.url)||'#')}" target="_blank" rel="noopener noreferrer">View on ${esc(names[album.source.provider])} ↗</a>`;
    section.querySelector('.album-track-list').innerHTML=records.map((m,i)=>{const entry=owned(fromMetadata(m));return `<div class="album-track-row"><span class="album-track-number">${esc(m.facts?.Disc&&m.facts.Disc!=='1'?m.facts.Disc+'.':'')}${esc(m.facts?.['Track number']||i+1)}</span><button type="button" data-track-view="${i}" class="album-track-title" aria-label="Preview song ${esc(m.title)}"><strong>${esc(m.title)}</strong><small>${esc((m.creators||[]).join(', '))}</small></button><span class="album-track-duration">${esc(m.facts?.Duration||'—')}</span><button type="button" data-track-add="${i}" ${entry?'disabled':''} aria-label="${entry?'In library':'Add song'}: ${esc(m.title)}">${entry?'✓ In library':'+ Add'}</button></div>`;}).join('')||'<p>No track listing supplied for this edition.</p>';
    section.querySelectorAll('[data-track-view]').forEach(b=>b.onclick=()=>{root.FolioDirectory?.before();container.closest('dialog').close();showLive(records[Number(b.dataset.trackView)]);});
    section.querySelectorAll('[data-track-add]').forEach(b=>b.onclick=()=>importLive(records[Number(b.dataset.trackAdd)],b));section.querySelector('.album-more').hidden=!data.more;root.FolioAlbumProgress?.bind(section,media,album,records,data.more);
   }catch(e){if(current===generation&&e.name!=='AbortError'){section.querySelector('.album-track-status').textContent=e.message+' Try Refresh tracks or choose another catalog.';}}
   finally{if(current===generation){section.setAttribute('aria-busy','false');section.querySelector('.album-track-list').inert=false;section.querySelector('.album-more').disabled=false;}}
  }
  section.querySelector('select').onchange=()=>load();section.querySelector('.album-refresh').onclick=()=>load(false,true);section.querySelector('.album-more').onclick=()=>load(true);load();
 }
 root.FolioAlbumTracks={bind};
})(globalThis);
